      "title": "Stories, Art, and Music as Historical Clues",
      "essentialQuestion": "How can stories and creative works help us learn about people and times?",
      "vocabulary": [
        "story",
        "art",
        "music",
        "context"
      ],
      "keyIdea": "Stories, art, and music can be valuable sources about ideas and experiences, but we should ask who created them, when, why, and what they can and cannot tell us.",
      "lessons": [
        {
          "day": "Monday",
          "title": "Wonder & Build Background",
          "objective": "I can ask and answer questions about stories, art, and music as historical clues.",
          "activity": "Examine an age-appropriate historical image, song excerpt without copyrighted lyrics, or public-domain folk-art example.",
          "evidence": "Teacher observation + learner explanation or drawing."
        },
        {
          "day": "Tuesday",
          "title": "Disciplinary Practice",
          "objective": "I can use a Social Studies tool or concept to organize what I notice.",
          "activity": "Ask source questions: Who made it? When? For whom? Why?",
          "evidence": "Hands-on sort, map, sequence, tally, comparison, or model."
        },
        {
          "day": "Wednesday",
          "title": "Source & Evidence Lab",
          "objective": "I can study a source or clue and say what it shows.",
          "activity": "Compare what an artwork shows directly with what we infer.",
          "evidence": "Notice / evidence / question record; oral dictation accepted."
        },
        {
          "day": "Thursday",
          "title": "Create, Decide, or Take Informed Action",
          "objective": "I can use what I learned to make or explain a responsible choice.",
          "activity": "Create an original class artwork or soundscape about community and write/dictate a source label.",
          "evidence": "Learner-created product, explanation, or safe civic-action simulation."
        },
        {
          "day": "Friday",
          "title": "Mastery, Reflection & Portfolio",
          "objective": "I can show what I understand and explain one piece of evidence.",
          "activity": "Review the week's vocabulary and key idea; complete the randomized five-question mastery check with read-aloud support if needed; correct misunderstandings; save one portfolio artifact and dictate or write one reflection sentence.",
          "evidence": "Best quiz score + one portfolio artifact + reflection."
        }
      ],
